// Supabase Edge Function "api".
// Every request to https://<project>.supabase.co/functions/v1/api/... arrives
// here with the path /api/..., which matches the routes in server/app.ts.
// app.bundle.js is generated by `node edge/build.mjs` (run by deploy-supabase.bat).

type Handler = (req: Request) => Response | Promise<Response>

let handler: Handler | null = null
let bootError = ""

try {
  const mod = await import("./app.bundle.js")
  const app = mod.default
  handler = (req) => app.fetch(req)
} catch (err) {
  // Shown in the Supabase logs and (briefly) in the response, so a broken
  // deploy explains itself instead of a bare WORKER_ERROR.
  bootError = err instanceof Error ? `${err.name}: ${err.message}` : String(err)
  console.error("[api] failed to start:", err)
}

Deno.serve((req) => {
  if (handler) return handler(req)
  return new Response(
    JSON.stringify({ error: { code: "BOOT_ERROR", message: bootError, details: null } }),
    { status: 500, headers: { "content-type": "application/json" } },
  )
})
